#include "../src/player_data.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2){std::cerr<<"usage: player_pack_check <seal_A_des.spr>\n";return 2;}auto p=socom::LoadPlayerPack(argv[1]);std::cout<<"SOCOM player pack v"<<p.version<<"\n"<<"vertices: "<<p.vertices.size()<<"\ntriangles: "<<p.vertices.size()/3<<"\nbatches: "<<p.batches.size()<<"\ntextures: "<<p.textures.size()<<"\njoints: "<<p.joints.size()<<"\nclips: "<<p.clips.size()<<"\n";for(const auto&c:p.clips)std::cout<<"  "<<c.name<<" samples="<<c.sampleCount<<" rate="<<c.sampleRate<<" duration="<<c.duration<<"\n";std::vector<socom::Mat4f> skin;socom::EvaluatePlayerSkin(p,0,0.0f,skin);std::cout<<"skin matrices: "<<skin.size()<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 1;}}
